    private static Dictionary<string, TextResource> Text() => new[] { new TextResource("text.prompt.collect-crystal", "Collect crystal", ["prompt"], "m021"), new TextResource("text.prompt.activate-switch", "Activate switch", ["prompt"], "m021"), new TextResource("text.prompt.open-door", "Open door", ["prompt"], "m021"), new TextResource("text.prompt.locked-door", "Locked — requires crystal and vault power", ["prompt"], "m021"), new TextResource("text.notification.item-collected", "Crystal collected", ["notification"], "m021"), new TextResource("text.notification.switch-activated", "Switch activated", ["notification"], "m021"), new TextResource("text.notification.door-opened", "Door opened", ["notification"], "m021"), new TextResource("text.notification.save-created", "Save created", ["notification"], "m021") }.ToDictionary(x => x.Id, StringComparer.Ordinal);
