    private static IReadOnlyList<object> Compose(IReadOnlyList<object> camera, IReadOnlyList<UiLayoutRecord> layout, IReadOnlyList<TextCommand> text, IReadOnlyList<ParticleSample> particles, string scenario, bool postLoad) => new object[] { new { order = 1, space = "world", kind = "authoritative-world", source = "immutable-runtime-snapshot" }, new { order = 2, space = "world", kind = "particles", count = particles.Count, source = "effect.collection-burst" }, new { order = 3, space = "world", kind = "camera-transform-and-clip", source = "camera.player-follow" }, new { order = 4, space = "screen", kind = "ui-layout", count = layout.Count, source = "ui.player-hud" }, new { order = 5, space = "screen", kind = "text-commands", count = text.Count, source = "font.ui.default" }, new { order = 6, space = "screen", kind = "final-frame", scenario, postLoad, fingerprint = Fingerprint(new { layout, text, particles, scenario, postLoad }) } };
    private static IReadOnlyList<PresentationEvent> Events() => [new("event.collection.0001", "item.collected", 1, "player", "crystal", "4,3", "post-commit"), new("event.damage.0001", "entity.damaged", 2, "hazard", "player", "5,3", "post-commit"), new("event.switch.0001", "switch.activated", 4, "player", "switch.vault", "8,3", "post-commit"), new("event.door.0001", "door.opened", 5, "player", "door.vault", "12,3", "post-commit"), new("operation.save.0001", "save.created", 6, null, null, "screen", "successful-persistence-operation")];
    private static Task Json(string directory, string name, object value) { Directory.CreateDirectory(directory); return File.WriteAllTextAsync(Path.Combine(directory, name), JsonSerializer.Serialize(value, CanonicalJson.Options)); }
    private static Task Lines<T>(string directory, string name, IEnumerable<T> values) { Directory.CreateDirectory(directory); return File.WriteAllLinesAsync(Path.Combine(directory, name), values.Select(x => JsonSerializer.Serialize(x))); }
    private static string Fingerprint(object value) => PresentationDeterminism.Hash(JsonSerializer.Serialize(value));
